def _build() -> dict[str, dict[str, str]]:
    tables = {lang: {} for lang in LANGS}
    for row in _ROWS:
        german, *rest = row
        if len(rest) != len(LANGS):
            raise ValueError(german)
        for lang, value in zip(LANGS, rest):
            if german in tables[lang]:
                raise ValueError("doppelter Text: " + german)
            tables[lang][german] = value
    return tables


TABLES = _build()
